// Recorded sounds as unsigned 8-bit mono PCM in base64.
//
// voice: "Finger Podium!" as a stadium announcer, made from the "awb" voice of CMU Flite
//        (https://github.com/festvox/flite): stretched, re-pitched and given echoes.
// cheer: "19 Football Crowd - Reaction To Goal" by D.jones,
//        https://freesound.org/s/528799/, CC0. Changed: seconds 4 to 8, mixed to mono,
//        filtered, limited, faded and reduced to 8 bits.
// boo:   "crowd booing" by HowardV, https://freesound.org/s/264378/, CC0. Changed: seconds
//        0 to 4, with the same processing.
(function (root) {
  'use strict';

  const api = {
    voice: {
      rate: 16000,
      data: '',
    },
    cheer: {
      rate: 11025,
      data: '',
    },
    boo: {
      rate: 11025,
      data: '',
    },
  };
  if (typeof module !== 'undefined') module.exports = api;
  else root.Sounds = api;
})(this);
